import React, {createContext, useContext, useState, useEffect, type ReactNode} from 'react';
import {ArrowLeft, ArrowRight, CaretDown, CaretRight, CalendarBlank, SuitcaseRolling, House, Compass, ChatCircle, Sparkle, CheckCircle, Check, QrCode, Key, WifiHigh, Coffee, Clock, MapPin, ForkKnife, Minus, Plus, X, PaperPlaneTilt, Star, Bell, ShieldCheck, DoorOpen, SignOut, Headset, FlowerLotus, Tree, Buildings, Copy, Info, ArrowCounterClockwise, Shower, WashingMachine, Armchair, LockKey} from '@phosphor-icons/react';
