type Page = 'home'|'arrival'|'luggage'|'drop'|'collect'|'room'|'concierge'|'services'|'food'|'hotel'|'checkout'|'beyond'|'directions'|'housekeeping';
type BagState = 'none'|'reserved'|'tagged'|'stored'|'released'|'collected';
type Msg = {role:'guest'|'concierge';text:string;actions?:{label:string;page:Page}[]};
type FoodLine={name:string;quantity:number};
type State = {checkoutAmount:number;language:'en'|'ja'|'zh'|'ms'|'ko'|'fr';prechecked:boolean;arrivalTime:string;storageDay:string;storageTime:string;bagDoorOpen:boolean;housekeeping:{kind:string;time:string;notes:string;status:'requested'|'completed'|'cancelled'}|null;arrived:boolean;ready:boolean;unlocked:boolean;departed:boolean;bag:BagState;bagCount:number;bagSize:string;order:'none'|'preparing'|'ready'|'collected';cartItems:FoodLine[];orderItems:FoodLine[];request:string;saved:string[]};
const initial:State={checkoutAmount:0,language:'en',prechecked:false,arrivalTime:'1pm–2pm',storageDay:'23 Sep',storageTime:'10:00',bagDoorOpen:false,housekeeping:null,arrived:false,ready:false,unlocked:false,departed:false,bag:'none',bagCount:1,bagSize:'Cabin bag',order:'none',cartItems:[],orderItems:[],request:'',saved:[]};
const initialMessages:Msg[]=[{role:'concierge',text:'Welcome to Cōsa, Mina. Your demo booking is linked. Complete pre-check-in before arrival. I can help you arrive, leave your bags and make the most of your stay.',actions:[{label:'Start arrival',page:'arrival'},{label:'Store my luggage',page:'luggage'}]}];
const Ctx=createContext<any>(null);
const useCosa=()=>useContext(Ctx) as {s:State;set:(p:Partial<State>)=>void;messages:Msg[];send:(v:string)=>void;notify:(v:string)=>void;setSheet:(v:string)=>void;sheet:string;reset:()=>void};
const config={name:'Cōsa',room:'B12',floor:'Level 2',locker:'L08',booking:'CSA-0913',guest:'Mina',dates:'23–26 Sep 2026'};
function screen(id:Page):FlowScreen{return{id,headerHeight:id==='home'?0:52,header:id==='home'?undefined:()=> <Toolbar page={id}/>,footerHeight:id==='concierge'?135:72,footer:()=>id==='concierge'?<><Composer/><Nav page={id}/></>:<Nav page={id}/>,render:()=> <PageContent page={id}/>};}
const titles:Record<Page,string>={home:'My stay',arrival:'Your arrival',luggage:'Luggage storage',drop:'Self-service bag drop',collect:'Collect luggage',room:'Your capsule',concierge:'Ask Cōsa',services:'Hotel services',food:'Food & delivery',hotel:'Hotel services',checkout:'Check out',beyond:'Beyond stay',directions:'Hotel directions',housekeeping:'Housekeeping'};
function IconCircle({children}:{children:ReactNode}){return <span className="icon-circle">{children}</span>}
function Button({children,onClick,secondary=false,disabled=false,...props}:any){return <button className={secondary?'button secondary':'button primary'} onClick={onClick} disabled={disabled} {...props}>{children}</button>}
function Row({icon,title,detail,onClick}:any){return <button className="service-row" onClick={onClick}><IconCircle>{icon}</IconCircle><span><strong>{title}</strong>{detail&&<small>{detail}</small>}</span><CaretRight size={21}/></button>}
function QR({kind='arrival',large=false}:{kind?:string;large?:boolean}){return <img className={large?'qr large':'qr'} src={`/assets/cosa/qr-${kind}.png`} alt={`Demo ${kind} QR code`} draggable={false}/>}
function Toolbar({page}:{page:Page}){const f=useFlow(),t=useText();return <div className="toolbar"><button className="icon-button" aria-label="Back to previous screen" onClick={()=>f.canGoBack?f.pop():f.replace(screen('home'))}><ArrowLeft size={24}/></button><span>{t(titles[page],({home:"滞在",arrival:"チェックイン",luggage:"荷物保管",drop:"荷物預け入れ",collect:"荷物受け取り",room:"カプセル",concierge:"Cōsaに相談",services:"ホテルサービス",food:"フード配送",hotel:"ホテルサービス",checkout:"チェックアウト",beyond:"滞在後",directions:"館内案内",housekeeping:"ハウスキーピング"})[page])}</span><button className="icon-button" aria-label="Get help" onClick={()=>f.push(screen('concierge'))}><Headset size={23}/></button></div>}
function Nav({page}:{page:Page}){const f=useFlow(),t=useText();return <nav className="bottom-nav" aria-label="Main navigation">{([{id:'home',text:t('Stay','滞在'),Icon:House},{id:'hotel',text:t('Hotel','ホテル'),Icon:Buildings},{id:'concierge',text:t('Concierge','コンシェルジュ'),Icon:ChatCircle}] as const).map(({id,text,Icon})=><button key={id} aria-current={(page===id||(id==='home'&&!['hotel','concierge'].includes(page)))?'page':undefined} onClick={()=>f.replace(screen(id))}><Icon weight={page===id?'fill':'regular'} size={25}/><span>{text}</span></button>)}</nav>}
function Main({children,className=''}:{children:ReactNode;className?:string}){return <MobileScroll className="cosa-scroll"><main className={`page-content ${className}`}>{children}</main></MobileScroll>}
function Eyebrow({children}:any){return <p className="eyebrow">{children}</p>}
function Step({n,title,detail,done=false,active=false}:any){return <div className={`step ${done?'done':''} ${active?'active':''}`}><span className="step-marker">{done?<Check size={17} weight="bold"/>:n}</span><div><strong>{title}</strong><p>{detail}</p></div></div>}
